for expert in topics:
    random.shuffle(topics[expert])
    blocks = []
    for i in range(30000):
        q, a = topics[expert][i % len(topics[expert])]
        block = mt([("User", q), ("Joe", a), ("User", q), ("Joe", a)])
        blocks.append(block)
    random.shuffle(blocks)
    out_path = f'data/experts/{expert}/unmerged_data.txt'
    os.makedirs(os.path.dirname(out_path), exist_ok=True)
    with open(out_path, 'w') as f:
        for block in blocks:
            f.write(block.rstrip() + '\n\n')
    print(f"Generated {len(blocks)} blocks for {expert}")

for expert in topics:
    all_qs = set()
    for i in range(30000):
        q, a = topics[expert][i % len(topics[expert])]
        all_qs.add(q)
    print(f"{expert}: {len(all_qs)} unique first questions in generated blocks")
